CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash TEXT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'USD',monthly_income_target NUMERIC(14,2) NOT NULL DEFAULT 0,notify_budget BOOLEAN NOT NULL DEFAULT TRUE,notify_weekly BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(50) NOT NULL,type VARCHAR(10) NOT NULL CHECK(type IN('INCOME','EXPENSE')),color VARCHAR(7) NOT NULL DEFAULT '#5b7cfa',icon VARCHAR(40) NOT NULL DEFAULT 'circle',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,name,type));
CREATE UNIQUE INDEX IF NOT EXISTS categories_system_unique ON categories(name,type) WHERE user_id IS NULL;
CREATE TABLE IF NOT EXISTS transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id UUID NOT NULL REFERENCES categories(id),type VARCHAR(10) NOT NULL CHECK(type IN('INCOME','EXPENSE')),amount NUMERIC(14,2) NOT NULL CHECK(amount>0),description VARCHAR(140) NOT NULL,date DATE NOT NULL,payment_method VARCHAR(30) NOT NULL DEFAULT 'Other',notes VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS transactions_user_date ON transactions(user_id,date DESC);CREATE INDEX IF NOT EXISTS transactions_user_category ON transactions(user_id,category_id);CREATE INDEX IF NOT EXISTS transactions_user_type ON transactions(user_id,type);
CREATE TABLE IF NOT EXISTS budgets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id UUID NOT NULL REFERENCES categories(id),amount NUMERIC(14,2) NOT NULL CHECK(amount>0),month SMALLINT NOT NULL CHECK(month BETWEEN 1 AND 12),year SMALLINT NOT NULL CHECK(year BETWEEN 2000 AND 2200),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,category_id,month,year));
CREATE TABLE IF NOT EXISTS recurring_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id UUID NOT NULL REFERENCES categories(id),type VARCHAR(10) NOT NULL CHECK(type IN('INCOME','EXPENSE')),amount NUMERIC(14,2) NOT NULL CHECK(amount>0),description VARCHAR(140) NOT NULL,frequency VARCHAR(10) NOT NULL CHECK(frequency IN('WEEKLY','MONTHLY','YEARLY')),start_date DATE NOT NULL,end_date DATE,active BOOLEAN NOT NULL DEFAULT TRUE,last_generated_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(120) NOT NULL,message VARCHAR(500) NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
